#!/bin/sh
# Autogenerated test: runs inside a container built from each compatibility image with packer installed with the
# default option (version latest), as the image's remote user. POSIX sh, because alpine:3.24 ships no bash.
set -eu

# The path is computed from $0 at run time, so shellcheck cannot follow it.
# shellcheck source=/dev/null
. "$(dirname "$0")/checks.sh"

# Before packer runs at all: every packer run writes a file under ~/.config/packer or ~/.packer.d, so it cannot pass as
# written by the install. A .gnupg directory may exist only empty: opensuse/leap:16.0 ships an empty /root/.gnupg.
no_packer_files_in_homes() {
  for no_packer_files_home in "${HOME}" /root; do
    for no_packer_files_path in .config/packer .packer.d .packerconfig .cache/packer; do
      if as_root test -e "${no_packer_files_home}/${no_packer_files_path}"; then
        printf '  found: %s/%s\n' "${no_packer_files_home}" "${no_packer_files_path}"
        return 1
      fi
    done
    no_packer_files_gnupg="$(as_root sh -c "${FILES_UNDER}" sh "${no_packer_files_home}/.gnupg")" || return 1
    if [ -n "${no_packer_files_gnupg}" ]; then
      printf '  found:\n%s\n' "${no_packer_files_gnupg}"
      return 1
    fi
  done
}
check "neither home holds a Packer configuration, plugin, or cache path, or a .gnupg directory that holds a file" \
  no_packer_files_in_homes

no_packer_variables() {
  no_packer_variables_set="$(env | grep -E '^(PACKER|CHECKPOINT)_' || true)"
  if [ -n "${no_packer_variables_set}" ]; then
    printf '  set: %s\n' "${no_packer_variables_set}"
    return 1
  fi
}
check "no environment variable starting with PACKER_ or CHECKPOINT_ is set" no_packer_variables

# Computed at run time: the default option installs whatever release the Checkpoint service reports as current.
latest="$(latest_release)"

check "command -v packer resolves to /usr/local/bin/packer" packer_resolves_to_usr_local_bin
# By mode, not `test -x`: the test runs as root on most images, and root passes `test -x` with any execute bit.
packer_executable_by_every_user() {
  packer_mode="$(stat -c '%a %U' /usr/local/bin/packer)" || return 1
  printf '  mode and owner: %s\n' "${packer_mode}"
  [ "${packer_mode}" = "755 root" ]
}
check "/usr/local/bin/packer is executable by every user" packer_executable_by_every_user
check "packer version reports the release the Checkpoint service reports as current" packer_reports_version "${latest}"
# The archive of a current release also holds LICENSE.txt.
check "nothing else of the archive is installed beside packer" sh -c '! test -e /usr/local/bin/LICENSE.txt'

# almalinux:9 ships cracklib's /usr/sbin/packer, a link to cracklib-packer; the other images have no other packer.
# shellcheck source=/dev/null
os_id="$(. /etc/os-release && printf '%s\n' "${ID:-}")"
if [ "${os_id}" = "almalinux" ]; then
  other_packer_left_alone() {
    other_packer_link="$(readlink /usr/sbin/packer)" || return 1
    printf '  /usr/sbin/packer -> %s\n' "${other_packer_link}"
    [ "${other_packer_link}" = "cracklib-packer" ]
  }
  check "the other package's /usr/sbin/packer is left as it was" other_packer_left_alone
fi

# The null builder and the shell-local provisioner are built in, so the template needs no plugin and no network.
template_with_built_in_components() {
  template_dir="$(mktemp -d)" || return 1
  cat >"${template_dir}/example.pkr.hcl" <<'TEMPLATE'
source "null" "example" {
  communicator = "none"
}

build {
  sources = ["source.null.example"]

  provisioner "shell-local" {
    inline = ["echo hello from packer > result.txt"]
  }
}
TEMPLATE
  template_status=0
  (
    cd "${template_dir}" \
      && isolated_packer validate . \
      && isolated_packer build -color=false .
  ) || template_status=$?
  template_result="$(cat "${template_dir}/result.txt" 2>/dev/null || true)"
  rm -rf "${template_dir}"
  printf "  status: %s, result: '%s'\n" "${template_status}" "${template_result}"
  [ "${template_status}" -eq 0 ] && [ "${template_result}" = "hello from packer" ]
}
check "packer validate and build run a template with built-in components" template_with_built_in_components

prerequisites_on_path() {
  for prerequisites_command in curl gpg unzip; do
    if ! command -v "${prerequisites_command}" >/dev/null 2>&1; then
      printf '  %s is not on PATH\n' "${prerequisites_command}"
      return 1
    fi
  done
}
check "curl, gpg, and unzip are on PATH after the install" prerequisites_on_path
check "the package managers' caches hold no package index or downloaded package" package_caches_clean
check "no temporary directory or staged file of the install remains" no_install_leftovers

reportResults
